731	  gl_FragColor = vec4(pjInverse(col), 1.0);
732	  if (uDbg > 0.5) {
733	    // 1: sub-band stripes (red even / blue odd, brightness = position in the sub-band), lip green, groove black
734	    vec3 dc = dbgSi < 0.0 ? vec3(0.5) : (mod(dbgSi, 2.0) < 0.5 ? vec3(1.0, 0.0, 0.0) : vec3(0.0, 0.3, 1.0)) * (0.25 + 0.75 * dbgXs);
735	    if (part > 0.5 && part < 1.5) dc = vec3(0.0, 1.0, 0.0);
736	    if (part > 1.5 && part < 2.5) dc = vec3(0.0);
