742	/** `m04river`: the wide painted river inside the tunnel — a curved trough (flat lane, sides rising to the walls) carrying
743	 * the approved water design (tile_river3: pink swirl ribbons, cyan streams, foam edges) by arc length across the trough,
744	 * two offset samples blended by slow world-anchored noise (no visible 4.7 u repeat), flowing down the slide, and the
745	 * glowing chevron arrows drawn crisp (distance field) on the centre lane. */
746	const RIVER_VERT = /* glsl */ `
747	uniform mat4 uProjVP;
748	attribute vec2 aR;          // x: signed arc length across the trough (u), y: 0 (r19b m04wup: how far the climb is ramped in, 0..1)
749	varying vec4 vProj;
750	varying vec3 vL;
751	varying float vS;
752	varying float vC;
753	void main() {
754	  vec4 wp = modelMatrix * vec4(position, 1.0);
755	  vProj = uProjVP * wp;
756	  vL = position;
757	  vS = aR.x;
758	  vC = aR.y;
759	  gl_Position = projectionMatrix * viewMatrix * wp;
760	}`;
761	const RIVER_FRAG = /* glsl */ `
762	uniform sampler2D uPlate;
763	uniform vec4 uPjPost;
764	uniform vec2 uPjRes;
765	uniform float uAway;
766	uniform sampler2D uRiv;
767	uniform vec4 uRivA;          // lateral half-width, along start, along length, lateral scale
768	uniform vec3 uLane;          // r13 m04lane: x on, y clean-lane half width (u), z strength
769	uniform vec2 uLane3;         // r13 m04lcd / m04lcw: deeper blue along the arrow line (strength, half width)
770	uniform vec2 uLane4;         // r14 m04lcn: deep-blue fade-in window ahead of the camera (start, full); off when y <= x
771	uniform vec4 uLane2;         // r13 m04lane2: x swirl detail, y gloss, z sparkle
772	uniform vec4 uEdge;          // r13 m04edge: x on, y half arc to the edge, z fringe width, w strength
773	uniform vec2 uSE;            // r13 m04rse / m04rsl: the climbing side water as long flowing currents (along stretch, from |lat|)
774	uniform float uTime;
775	uniform vec4 uArr;           // arrow spacing, first arrow (along), half width, arm thickness
776	uniform float uZ0;
777	uniform vec4 uPk;            // m04pink: x on, y cyan lane half width, z outer edge of the pink bands, w strength
778	uniform float uPkH;          // r14 m04pkh: pink only where the painted tile is pink (0 = off)
779	uniform sampler2D uSB;       // r15 m04sband: the painted swirl bands (tile_side04: across = lane side .. wall side reversed)
780	uniform vec4 uSB0;           // x strength, y inner |arc| where the bands start, z outer |arc| (water edge), w tile length along (u)
781	uniform vec4 uSB1;           // x blend width at the inner side, y re-apply the lilac-white edge fringe (0/1), z tile part used
782	                             // (1 = cyan..lilac, less = start nearer the pink ribbon), w slow lateral wander of the bands (u)
783	uniform vec2 uSB2;           // far ahead of the camera (x -> y u) the bands smooth into long unbroken stripes (no repeat ribs)
784	uniform vec4 uNB;            // r17 m04nband: x on, y Benny along (local), z Benny lateral, w inner arc hugging Benny (u)
785	uniform vec4 uNB2;           // r17 m04nband: x bands back at the normal inner arc this far ahead of Benny (u), y widening behind Benny (b * d^2; < 0 = straight |b| per u)
786	                             // behind Benny, z extra pinch at Benny's sides (u), w lateral follow of Benny (0..1)
787	uniform vec2 uNB3;           // r17 m04nband: x width of one cyan -> pink half stripe near Benny (u; 0 = one stretched band), y tile span
788	uniform vec4 uNB4;           // r18 m04nwhirl: x along squash of the whirl ellipse behind Benny (0 = off), y its centre ahead of Benny (u),
789	                             // z S-meander amplitude of the band edge ahead of Benny (u, 0 = off), w meander wavelength (u)
790	uniform float uNB5;          // r18 m04nwhirl: spiral twist (stripe periods per half turn round Benny; 0 = closed U rings)
791	uniform vec2 uNB6;           // r18 m04nwhirl: cyan corridor straight behind Benny — x half width (u, 0 = off), y soft edge (u)
792	uniform vec2 uNB7;           // r18 m04nwq / m04nwr: x clean lane water where the whirl leaves the water bare (0/1), y whirl radius
793	                             // round Benny (u; 0 = unlimited) — beyond it the bands run straight again (no smear when the camera lags)
794	uniform vec4 uSS;            // r18 m04sswirl: x swing of the band pattern across the bank (u, 0 = off), y its wavelength along (u),
795	                             // z how far the water's top edge laps back down in tongues (u, 0 = straight edge), w lap wavelength (u)
796	uniform vec4 uWU;            // r19b m04wup: x highest climb up the wall above the old water edge (arc u, 0 = off), y tongue
797	                             // wavelength along (u), z tongue depth (0..1 of the climb), w share of the painted band sequence
798	                             // reached at the old edge (the rest — pink satin -> lilac crest — climbs the wall)
799	uniform vec4 uWU2;           // r19b m04wup: x / y the climb falls from full (x u ahead of Benny) to z of it (y u ahead), w soft top edge (u)
800	uniform vec4 uWU3;           // r19b m04wup: x old water edge (arc u), y tongue drift with the current (0..1), z lilac-white lace
801	                             // on the climbing crest (share of the m04edge fringe), w band tile column at the crest (0 = lilac sparkle)
802	uniform vec2 uFar;           // r20 m04farsm: x where the K9 telescope begins (along, local), y on — beyond it the band edges run smooth
803	uniform vec4 uWC;            // r20 m04wcr: x on (strength), y bands per u up the wall, z bright highlight lines, w dark violet edges
804	uniform vec2 uWC2;           // r20 m04wcr: x bright glossy lip just under the crest, y soft top width (u) instead of m04wus
805	uniform vec4 uA5;        // m04arr5: x on, y spacing, z first apex (along), w bar thickness along the flow
806	uniform vec4 uA5b;           // m04arr5: x half width, y arm slope (along per lateral), z camera along, w visible depth
807	uniform vec2 uA5n;           // r10 m04arr5: near fade-in distance (start, full) ahead of the camera; default 6.5, 9.0
808	varying vec4 vProj;
809	varying vec3 vL;
810	varying float vS;
811	varying float vC;
812	${PROJ05_INVERSE}
813	float h21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
814	float vn(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
815	  return mix(mix(h21(i), h21(i + vec2(1, 0)), f.x), mix(h21(i + vec2(0, 1)), h21(i + vec2(1, 1)), f.x), f.y); }
816	// chevron pointing down the slide: distance to the two arms
817	float chev(vec2 p, float hw, float th) {
818	  p.x = abs(p.x);
819	  vec2 a = vec2(0.0, 0.0), b = vec2(hw, -hw * 2.3);   // long arms along the flow (painted arrows seen low)
820	  vec2 pa = p - a, ba = b - a;
821	  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
822	  return length(pa - ba * h) - th;
823	}
824	void main() {
825	  float along = -vL.z;                                     // down the slide from Benny's checkpoint water point
826	  float flow = along - uTime * 0.9;                        // the design drifts down the slide with the current
827	  float lat = vS * uRivA.w + 0.9 * (vn(vec2(along * 0.07, 7.0)) - 0.5) * smoothstep(0.4, 1.6, abs(vS));
828	  float fl = flow + 2.2 * (vn(vec2(along * 0.05, vS * 0.15 + 1.0)) - 0.5);
829	  float se = 1.0 + (uSE.x - 1.0) * smoothstep(uSE.y, uSE.y + 0.9, abs(vS));
830	  vec2 uv1 = vec2(lat / (2.0 * uRivA.x) + 0.5, (fl - uRivA.y) / (uRivA.z * se));
831	  vec2 uv2 = vec2(-lat / (2.0 * uRivA.x) * 0.96 + 0.5, (fl - uRivA.y) / (uRivA.z * se) * 0.77 + 0.37);
832	  float w = smoothstep(0.3, 0.7, vn(vec2(along * 0.16, vS * 0.35 + 3.0)));
833	  vec3 col = mix(texture2D(uRiv, uv1).rgb, texture2D(uRiv, uv2).rgb, w);
834	  vec3 tileC = col;                                        // r14: the painted tile colour before any re-colouring
835	  vec3 laneCol = col;                                      // r18: the clean lane water (for the bare parts of the whirl)
836	  // the deeper cyan centre lane of the painting
837	  col = mix(col, col * vec3(0.55, 0.85, 1.0) + vec3(0.0, 0.05, 0.12), 0.35 * (1.0 - smoothstep(0.9, 1.7, abs(vS))));
838	  if (uLane.x > 0.5) {
839	    // r13 m04lane: the painted centre path is ONE clean glossy blue lane (deep cyan-blue, soft long light streaks, no
840	    // foam crests or swirl knots): the tile seen heavily smoothed (mip bias) for its gentle light / dark flow, re-coloured
841	    // into the painted lane blues, plus a few long thin highlights running down the path
842	    float kl = 1.0 - smoothstep(uLane.y, uLane.y + 0.9, abs(vS));
843	    vec3 bl = mix(texture2D(uRiv, uv1, 4.5).rgb, texture2D(uRiv, uv2, 4.5).rgb, w);
844	    float lb = dot(bl, vec3(0.30, 0.55, 0.15));
845	    vec3 laneC = mix(vec3(0.02, 0.42, 0.88), vec3(0.30, 0.82, 1.0), smoothstep(0.35, 0.80, lb));
846	    float sk = vn(vec2(vS * 3.1 + 2.0, fl * 0.12));
847	    laneC += vec3(0.55, 0.85, 1.0) * 0.35 * smoothstep(0.80, 0.97, sk);
848	    if (uLane2.x > 0.0) {
849	      // r13 m04lane2: the painted lane as RICH glossy magical water — saturated electric blue -> electric cyan, the tile's
850	      // own swirls kept at a moderate blur (uLane2.x = detail), flowing glossy highlight ribbons, twinkling white sparkles
851	      vec3 dl = mix(texture2D(uRiv, uv1, 1.5).rgb, texture2D(uRiv, uv2, 1.5).rgb, w);
852	      float ld = mix(lb, dot(dl, vec3(0.30, 0.55, 0.15)), uLane2.x) + uLane2.w;   // w = brighter / more turquoise
853	      laneC = mix(vec3(0.00, 0.22, 0.86), vec3(0.00, 0.62, 1.00), smoothstep(0.20, 0.55, ld));
854	      laneC = mix(laneC, vec3(0.16, 0.92, 1.00), smoothstep(0.55, 0.82, ld));
855	      laneC = mix(laneC, vec3(0.80, 0.98, 1.00), uLane2.y * smoothstep(0.84, 0.97, ld));            // glossy crests
856	      float rib = vn(vec2(vS * 2.3 + 5.0, fl * 0.35));                                              // flowing highlight ribbons
857	      laneC += vec3(0.45, 0.85, 1.0) * 0.30 * uLane2.y * smoothstep(0.72, 0.92, rib) * (0.6 + 0.4 * sin(fl * 2.0 + vS));
858	      vec2 sc = vec2(vS * 5.0, fl * 3.0); vec2 si = floor(sc), sf = fract(sc) - 0.5;              // sparkles
859	      float sh = h21(si + 17.0);
860	      float tw = 0.5 + 0.5 * sin(uTime * 6.0 + sh * 40.0);
861	      float spk = smoothstep(0.16, 0.0, length(sf - (vec2(h21(si + 3.1), h21(si + 7.7)) - 0.5) * 0.6)) * step(0.86, sh) * tw;
862	      laneC += vec3(1.0) * uLane2.z * spk * (1.0 - smoothstep(0.3, 0.8, fwidth(sc.x)));
863	      // r13 m04lcd: the painted lane is DEEPER blue along the arrow line (the glassy arrows pop on it), brighter turquoise
864	      // toward the pink edges
865	      // r14 m04lcn=a,b: the deep blue only AHEAD of Benny (fades in from a to b u ahead of the camera; Benny ≈ 6.4 u
866	      // ahead) — the painted water round / behind him is bright cyan, the deep electric blue lies under the arrows
867	      float rk = uLane4.y > uLane4.x ? smoothstep(uLane4.x, uLane4.y, along - uA5b.z) : 1.0;
868	      float wl = rk * (1.0 - smoothstep(0.2, uLane3.y, abs(vS)));
869	      if (uLane4.y > uLane4.x && uLane4.x < 0.0) {
870	        // r14 m04lcn=-a,b (negative start): the PAINTED deep azure keyed on the water's own brightness, so the swirls,
871	        // glossy crests and white glints survive (a plain multiply flattened the lane into a dark royal-blue patch)
872	        float lq = dot(laneC, vec3(0.30, 0.55, 0.15));
873	        vec3 deep = mix(vec3(0.00, 0.40, 0.86), vec3(0.02, 0.66, 0.98), smoothstep(0.40, 0.88, lq));
874	        deep = mix(deep, laneC, smoothstep(0.90, 0.99, lq));                                     // keep only the white glints
875	        laneC = mix(laneC, deep, min(uLane3.x, 1.0) * smoothstep(-uLane4.x, uLane4.y, along - uA5b.z) * (1.0 - smoothstep(0.2, uLane3.y, abs(vS))));
876	      } else {
877	        laneC = mix(laneC, laneC * vec3(0.42, 0.70, 1.0), uLane3.x * wl);
878	      }
879	    }
880	    laneCol = laneC;
881	    col = mix(col, laneC, kl * uLane.z);
882	  }
883	  float fringe = 0.0, edgeY = uEdge.y;
884	  // r19b m04wup: as painted, the water does not stop in a straight flat line against the gold wall — the pink / magenta
885	  // satin bands sweep UP the tunnel sides in long rising tongues (higher round Benny, lower far ahead), their lilac crest
886	  // lapping the wall. ext = arc up the wall above the old water edge, wuE = this spot's top edge (both in u).
887	  float ext = abs(vS) - uWU3.x, wuE = 0.0, wuK = 0.0;
888	  if (uWU.x > 0.0) {
889	    float sd = vS < 0.0 ? 0.0 : 1.0;
890	    float bA = uNB.x > 0.5 ? uNB.y : uA5b.z + 6.4;                       // Benny's position down the slide
891	    float env = mix(1.0, uWU2.z, smoothstep(uWU2.x, uWU2.y, along - bA));
892	    float ph = (along - uTime * 0.9 * uWU3.y) * 6.2832 / uWU.y + sd * 2.6 + 2.2 * vn(vec2(along * 0.06, 3.0 + sd * 6.0));
893	    float tg = 0.5 + 0.5 * sin(ph);
894	    tg = tg * tg * (3.0 - 2.0 * tg);                                      // long rounded crests, short troughs
895	    wuK = clamp(vC, 0.0, 1.0);                                            // ramped in from the opening
896	    wuE = uWU.x * env * (1.0 - uWU.z * (1.0 - tg)) * wuK;
897	    edgeY = uWU3.x + wuE;                                                 // the lilac fringe rides the climbing crest
898	  }
899	  if (uSS.z > 0.0) {
900	    // r18 m04sswirl: the water's top edge against the gold wall laps up and down in soft tongues (painted: no straight
901	    // hard line where the water meets the wall); the lilac fringe follows the lapping edge
902	    float lw = 0.5 + 0.5 * sin(along * 6.2832 / uSS.w + (vS < 0.0 ? 0.7 : 2.9));
903	    lw = 0.65 * lw + 0.35 * vn(vec2(along * 0.8, vS < 0.0 ? 3.0 : 9.0));
904	    edgeY = uEdge.y - uSS.z * lw;
905	    if (abs(vS) > edgeY) discard;
906	  }
907	  if (uEdge.x > 0.5) {
908	    // r13 m04edge: soft irregular water edge against the gold wall — pink / magenta current then a lilac-white lacy fringe
909	    // in broken patches (no straight hard line, no tall foam): uEdge.y = half arc to the edge, z = fringe width, w = strength
910	    float ew = uEdge.z * mix(1.0, 0.45, wuK);                             // r19b m04wup: a narrower lace on the climbing crest
911	    float e = smoothstep(edgeY - ew, edgeY - 0.04, abs(vS));
912	    float n1 = vn(vec2(fl * 0.9, sign(vS) * 7.0 + abs(vS) * 2.0)), n2 = vn(vec2(fl * 2.7 + 3.0, abs(vS) * 6.0));
913	    float patchy = smoothstep(0.35, 0.75, 0.65 * n1 + 0.35 * n2);
914	    vec3 pinkC = mix(vec3(0.78, 0.16, 0.66), vec3(1.0, 0.45, 0.82), n2);
915	    col = mix(col, pinkC, uEdge.w * smoothstep(edgeY - uEdge.z * 2.2, edgeY - uEdge.z, abs(vS)) * (0.5 + 0.5 * n1));
916	    fringe = uEdge.w * e * patchy * mix(1.0, uWU3.z, wuK);
917	    col = mix(col, vec3(0.97, 0.90, 1.0), fringe);
918	  }
919	  if (uPk.x > 0.5) {
920	    // m04pink: the painted broad pink / magenta swirl bands either side of the cyan lane; the swirl structure (the
921	    // tile's brightness) is kept, re-coloured into the painted magenta -> hot pink -> pale pink, with cyan streaks left
922	    float side = smoothstep(uPk.y, uPk.y + 0.7, abs(vS)) * (1.0 - smoothstep(uPk.z, uPk.z + 0.9, abs(vS)));
923	    float l = dot(col, vec3(0.30, 0.55, 0.15));
924	    vec3 pk = mix(vec3(0.55, 0.08, 0.58), vec3(0.96, 0.30, 0.78), smoothstep(0.22, 0.58, l));
925	    pk = mix(pk, vec3(1.0, 0.78, 0.96), smoothstep(0.66, 0.95, l));
926	    float n = vn(vec2(fl * 0.22, vS * 0.6 + 11.0));
927	    float keepCyan = smoothstep(0.62, 0.85, n);                       // a few cyan swirls survive inside the pink
928	    float pkMix = 1.0 - 0.75 * keepCyan;
929	    if (uPkH > 0.0) {
930	      // r14 m04pkh=x: the PAINTED band structure — re-colour only where the painted tile itself is pink / magenta (red
931	      // above green); its cyan streaks between the satin bands stay cyan (x = how strictly; 0 = old uniform pink)
932	      float pinkness = smoothstep(-0.04, 0.22, tileC.r - tileC.g);
933	      pkMix = mix(pkMix, 0.12 + 0.88 * pinkness, uPkH);
934	    }
935	    col = mix(col, pk, side * uPk.w * pkMix);
936	  }
937	  if (uSB0.x > 0.0) {
938	    // r15 m04sband: the side water carries the PAINTED swirl bands (cyan streaks by the lane -> violet -> hot-pink satin
939	    // ribbon -> lilac sparkle at the wall), cut from references/04 (tools/match04/sideband04.py), by arc length across the
940	    // trough and world position along it (flowing with the current), two offset samples blended like the river tile
941	    float inner = uSB0.y, sv = vS, rr = -1.0, mea = 0.0, twp = 0.0, ckc = 1.0;
942	    if (uNB.x > 0.5) {
943	      // r17 m04nband: the painted bands sweep in close round Benny (inner edge hugging him at his position and behind
944	      // him toward the camera) and curve back out to the normal lane width ahead of him (arrow lane stays cyan); the band
945	      // pixels stay world-anchored and flowing, only where they start follows Benny down the slide
946	      float d = along - uNB.y;
947	      sv = vS - uNB.z * uNB2.w;
948	      float db = max(-d, 0.0), hug = uNB.w + uNB2.y * (uNB2.y < 0.0 ? -db : db * db) - uNB2.z * exp(-d * d / 1.2);  // < 0: straight widening
949	      if (uNB4.x > 0.0) {
950	        // r18 m04nwhirl: as painted, the bands WRAP round Benny like a whirl — behind him (toward the camera) they no longer
951	        // open outward but close in under him: the band edge is an ellipse centred on Benny (cyan pocket + splash round
952	        // him), so the pink / cyan stripes curve in from both sides and cross under him in crescents
953	        hug = uNB.w - uNB2.z * exp(-d * d / 1.2);
954	        float fo = mix(1.0, uNB2.w, smoothstep(0.0, uNB2.x, d));            // centred on Benny at / behind him
955	        vec2 wq = vec2(vS - uNB.z * fo, uNB4.x * min(d - uNB4.y, 0.0));
956	        rr = length(wq);
957	        float wf = uNB7.y > 0.0 ? 1.0 - smoothstep(uNB7.y - 1.0, uNB7.y, rr) : 1.0;   // r18 m04nwr: whirl only near Benny
958	        // spiral, not closed rings: a stripe hugging Benny's left side sweeps under him and comes out farther out on his
959	        // right (uNB5 stripe periods per half turn; whole numbers leave the bands ahead of him unchanged)
960	        twp = uNB5 * 2.0 * uNB3.x * abs(atan(wq.y, wq.x)) / 3.14159 * wf;
961	        // as painted, the water right round and straight below Benny stays cyan (white splash); the pink sweeps in from the
962	        // lower-left / lower-right and fades out before the middle (no magenta pool under him)
963	        if (uNB6.x > 0.0) ckc = 1.0 - smoothstep(uNB4.y, uNB4.y - 1.0, d) * (1.0 - smoothstep(uNB6.x - uNB6.y, uNB6.x, abs(wq.x)));
964	        // r18 m04nwq: where the whirl leaves the water bare (pocket / corridor round Benny) show the clean glossy lane water, not
965	        // the raw painted tile magnified into big white cloud blobs (seen beside Benny while he steers to the side)
966	        if (uNB7.x > 0.5) {
967	          // m04nwq=2: the painted cyan streaks of the band strip's lane side instead (crisp at any distance, flowing along)
968	          vec3 bare = laneCol;
969	          if (uNB7.x > 1.5) {
970	            // walk across the cyan part of the strip with the lateral position and offset each lane along, so the streaks
971	            // run with the flow side by side (one column alone gives bands straight across the river)
972	            float uq = 0.87 + 0.12 * (0.5 + 0.5 * sin(vS * 2.3 + 0.8 * vn(vec2(vS * 0.9, along * 0.05))));   // cyan end only
973	            float vq = fl / uSB0.w + 0.45 * vn(vec2(vS * 1.7 + 4.0, 2.0));
974	            bare = mix(texture2D(uSB, vec2(uq, vq)).rgb, texture2D(uSB, vec2(uq, vq * 0.81 + 0.29)).rgb, w);
975	          }
976	          col = mix(col, bare, (1.0 - smoothstep(uSB0.z - 1.2, uSB0.z - 0.6, abs(vS))) * (1.0 - smoothstep(uNB7.y > 0.0 ? uNB7.y : 9.0, (uNB7.y > 0.0 ? uNB7.y : 9.0) + 1.0, rr))
977	            * smoothstep(uNB4.y + 1.5, uNB4.y, d));                // only at / behind Benny: the arrow lane ahead stays as it was
978	        }
979	        rr = mix(abs(sv), rr, wf);
