// scratch: like tools/lead21/audit_screen.mjs but several variants in one vite/browser session
// usage: cd <worktree> && node multi.mjs <outRoot> <stage> <variantsFile: label<TAB>query per line>   (env SHOTS like AUDIT_SHOTS)
import { mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [OUT, STAGE, VF] = process.argv.slice(2);
const SHOTS = process.env.SHOTS ? JSON.parse(process.env.SHOTS)
  : [['a_start', 0, null], ['b_early', 0.12, null], ['c_middle', 0.35, null], ['d_late', 0.6, null], ['e_end', 0.85, null],
     ['f_hard_left', 0.35, -1], ['g_hard_right', 0.35, 1]];
const VARS = readFileSync(VF, 'utf8').split('\n').filter((l) => l.trim()).map((l) => l.split('\t'));
const { chromium } = loadPlaywright();
const vite = await startVite(Number(process.env.AUDIT_PORT ?? 5273));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  for (const [label, Q] of VARS) {
    const out = `${OUT}/${label}`; mkdirSync(out, { recursive: true });
    const log = [];
    const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
    page.on('pageerror', (e) => console.error('pageerror', e.message));
    page.on('console', (m) => { if (m.type() === 'error' && /Shader|WebGL|rror/.test(m.text())) console.error('console', m.text().slice(0, 400)); });
    await page.goto(`${vite.url}/?qa=1&dpr=1&${Q}`);
    await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
    for (const [name, frac, steer] of SHOTS) {
      const st = await page.evaluate(async ([stage, frac, steer]) => {
        const r = window.__rainbow;
        r.goto(stage);
        const s0 = r.state().s, s1 = r.course.stage(stage).s1;
        const tS = s0 + frac * (s1 - s0);
        r.setSteer(steer);
        let k = 0; while (r.state().s < tS && k < 6000) { r.step(1); k++; }
        r.setSteer(null);
        r.freezeAt(10);
        r.drawList();
        await new Promise((res) => requestAnimationFrame(() => res()));
        return { ...r.state(), s0, s1 };
      }, [STAGE, frac, steer]);
      await page.screenshot({ path: `${out}/${name}.png` });
      log.push({ name, frac, steer, s: st.s, lat: st.lat, coins: st.coins });
      console.log(label, name, 's', st.s.toFixed(2), 'lat', st.lat, 'coins', st.coins);
    }
    writeFileSync(`${out}/shots.json`, JSON.stringify(log, null, 1));
    await page.close();
  }
} finally { await browser.close(); await vite.close?.(); }
EOF
